    {showProjection&&<div className="customer-panel"><div className="customer-panel-head"><div><div className="eyebrow">Analytical only</div><h2>What-if projection</h2></div><span>No wallet impact</span></div><div className="form-two"><label>Amount (minor units)<input type="number" min="1" value={amount||10000} onChange={e=>setAmount(Number(e.target.value)||0)}/></label><label>Product rate<select value={selected?.id||""} onChange={e=>setSelected((dashboard.data?.products||[]).find((p:any)=>p.id===Number(e.target.value))||null)}><option value="">Choose product</option>{(dashboard.data?.products||[]).map((p:any)=><option key={p.id} value={p.id}>{p.name} · {(p.annualRateBps/100).toFixed(2)}%</option>)}</select></label></div>{projection.data&&<div className="customer-metric-grid"><div><span>Projected reward</span><strong>{display(projection.data.projectedRewardMinor)}</strong></div><div><span>Projected ending value</span><strong>{display(projection.data.projectedEndingMinor)}</strong></div><div><span>Estimated fees</span><strong>{display(projection.data.estimatedFeesMinor)}</strong></div></div>}<div className="test-notice"><ShieldCheck size={14}/> Projection results are estimates and do not alter the wallet, position, or ledger.</div></div>}
